L11_1 = "OMEN_CHARADE_INTERLUDE4@31#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L10_1.m_CutScenProcessKey = 0
L10_1.m_CutScenID = 8100115
L10_1.m_CutScenStrID = "OMEN_CHARADE_INTERLUDE4"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "<color=#ffd34c>오늘 오후, ARC-KN2 교외에서 일어난 원인 불명의 침식재난으로 다수의 사상자가 발생했습니다.</color>"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "<color=#ffd34c>本日午後、ARC-KN2郊外で起きた原因不明の侵食災害によって、複数の死傷者が発生しました。</color>"
L10_1.m_Talk_JPN = L11_1
L11_1 = "<color=#ffd34c>This afternoon, multiple casualties have been reported from the unexplained Corruption Disaster that occurred on the outskirts of ARC-KN2.</color>"
L10_1.m_Talk_ENG = L11_1
L11_1 = "<color=#ffd34c>今天下午在ARC-KN2郊區，發生不明原因的侵蝕災難，導致多人傷亡。</color>"
L10_1.m_Talk_TWN = L11_1
L11_1 = "<color=#ffd34c>This afternoon, multiple casualties have been reported from the unexplained Corruption Disaster that occurred on the outskirts of ARC-KN2.</color>"
L10_1.m_Talk_DEU = L11_1
L11_1 = "<color=#ffd34c>This afternoon, multiple casualties have been reported from the unexplained Corruption Disaster that occurred on the outskirts of ARC-KN2.</color>"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "OMEN_CHARADE_INTERLUDE4@32#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L11_1.m_CutScenProcessKey = 0
L11_1.m_CutScenID = 8100115
L11_1.m_CutScenStrID = "OMEN_CHARADE_INTERLUDE4"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "<color=#ffd34c>그 중에는 육상 대회에 참가하기 위해 이동 중이던 학생들도 포함되어 있어 큰 충격을 안겼습니다.</color>"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "<color=#ffd34c>中には陸上大会に参加するために移動していた学生たちも含まれており、大きな衝撃を与えました。</color>"
L11_1.m_Talk_JPN = L12_1
L12_1 = "<color=#ffd34c>Among the casualties are students who were on their way to a track event, causing much shock to the public.</color>"
L11_1.m_Talk_ENG = L12_1
L12_1 = "<color=#ffd34c>當中也有正要前往參與田徑賽的學生，因此造成相當大的衝擊。</color>"
L11_1.m_Talk_TWN = L12_1
L12_1 = "<color=#ffd34c>Among the casualties are students who were on their way to a track event, causing much shock to the public.</color>"
L11_1.m_Talk_DEU = L12_1
L12_1 = "<color=#ffd34c>Among the casualties are students who were on their way to a track event, causing much shock to the public.</color>"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "OMEN_CHARADE_INTERLUDE4@33#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L12_1.m_CutScenProcessKey = 0
L12_1.m_CutScenID = 8100115
L12_1.m_CutScenStrID = "OMEN_CHARADE_INTERLUDE4"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "<color=#ffd34c>현재 KN2 도시 관리국은 사상자 신원의 파악과 재난의 원인을 밝히는 데에 주력하고 있습니다.</color>"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "<color=#ffd34c>現在、KN2都市管理局は死傷者の身元の把握と災害の原因究明に努めています。</color>"
L12_1.m_Talk_JPN = L13_1
L13_1 = "<color=#ffd34c>Currently, the KN2 city administration is focusing its efforts towards identifying the victims and uncovering the cause of the disaster.</color>"
L12_1.m_Talk_ENG = L13_1
L13_1 = "<color=#ffd34c>至於傷亡人士的身分和災難發生的原因，KN2城市管理局目前正在積極調查中。</color>"
L12_1.m_Talk_TWN = L13_1
L13_1 = "<color=#ffd34c>Currently, the KN2 city administration is focusing its efforts towards identifying the victims and uncovering the cause of the disaster.</color>"
L12_1.m_Talk_DEU = L13_1
L13_1 = "<color=#ffd34c>Currently, the KN2 city administration is focusing its efforts towards identifying the victims and uncovering the cause of the disaster.</color>"
L12_1.m_Talk_FRA = L13_1
