L31_1 = "아니, 울기는커녕 탄광 같은 샤레이드 밑바닥에서 아득바득 기어 올라왔어."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "泣くどころか、炭鉱のようなシャレードのどん底から這い上がってきたわ。"
